<script setup lang="ts">import { ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { exportResumePdf,getResumes } from '@/utils/resume'; import type { ResumeData } from '@/utils/resume'; const list=ref<ResumeData[]>([]); onShow(()=>list.value=getResumes()); function edit(id:string){uni.navigateTo({url:`/pages/resume-edit/resume-edit?id=${id}`})} function create(){uni.navigateTo({url:'/pages/resume-edit/resume-edit?templateId=blue'})}</script>
<template><view class="page"><view class="title-row"><text class="title">我的简历</text><text class="stat-label">{{list.length}} 份已保存</text></view><view v-if="list.length" class="list"><view v-for="item in list" :key="item.id" class="card" @click="edit(item.id)"><view class="avatar">{{(item.name||'未').slice(0,1)}}</view><view class="info"><text class="name">{{item.name||'未命名简历'}}</text><text class="intent">{{item.intention||'尚未填写求职意向'}}</text><text class="time">更新于 {{item.updatedAt}}</text></view><button class="export" @click.stop="exportResumePdf(item)">导出 PDF</button></view></view><view v-else class="empty"><text class="empty-icon">＋</text><text class="empty-title">还没有简历</text><text class="empty-sub">从一个模板开始，创建你的第一份简历</text><button class="create" @click="create">创建简历</button></view></view></template>
